import { Router } from "express";
import * as c from "../controllers/index.js";
import { requireAuth, allowRoles, loginLimit, registrationLimit, } from "../middleware/security.js";
export const router = Router();
router.get("/health", (_req, res) => res.json({ status: "ok" }));
router.get("/public/privacy", c.privacy);
router.get("/public/provinces", c.getProvinces);
router.get("/public/seccionales", c.getSeccionales);
router.get("/public/schools", c.getSchools);
router.post("/public/registrations", registrationLimit, c.register);
router.post("/auth/login", loginLimit, c.login);
router.get("/auth/me", requireAuth, c.me);
router.post("/auth/logout", requireAuth, c.logout);
router.use("/private", requireAuth, allowRoles("ADMIN", "LEADER"));
router.get("/private/dashboard", c.dashboard);
router.get("/private/registrations", c.listRegistrations);
router.patch("/private/registrations/:id/status", c.updateStatus);
router.post("/private/registrations/:id/sensitive", allowRoles("ADMIN"), c.sensitiveData);
router.use("/private/admin", allowRoles("ADMIN"));
router.get("/private/admin/leaders", c.listLeaders);
router.post("/private/admin/leaders", c.createLeader);
router.get("/private/admin/users", c.listUsers);
router.post("/private/admin/users", c.createUser);
router.patch("/private/admin/users/:id", c.setUserActive);
router.put("/private/admin/leaders/:id/seccionales", c.assignSeccionales);
router.get("/private/admin/audit-logs", c.auditLogs);
router.post("/private/admin/provinces", c.createCatalog("province"));
router.post("/private/admin/seccionales", c.createCatalog("seccional"));
router.post("/private/admin/schools", c.createCatalog("school"));
